$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$public=Get-ChildItem $root -Filter *.html;$errors=@();foreach($file in $public){$text=Get-Content -Raw $file.FullName;if($text-match'[A-Za-z]:\\|localhost|javascript:void|href=""'){$errors+=$file.Name}};if($errors){throw "Unsafe production strings: $($errors-join', ')"};'No Windows paths, localhost, javascript:void or empty href in public HTML. Configuration placeholders remain intentionally documented.'
